    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        if (s.length() < minLen) {
            minLen = s.length();
        }
    }
    if (minLen == 0) {
        return 0;
    }
    String first = strings.get(0);
    for (int len = minLen; len >= 1; len--) {
        java.util.Set<String> candidates = new java.util.HashSet<>();
        for (int i = 0; i <= first.length() - len; i++) {
            candidates.add(first.substring(i, i + len));
        }
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (int idx = 1; idx < strings.size(); idx++) {
                String s = strings.get(idx);
                if (!(s.contains(cand) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

