public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate basic inputs
    if (n <= 0 || start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    // If start equals end, travel is trivially possible
    boolean same = true;
    for (int i = 0; i < n; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    java.util.function.Function<int[], String> keyFunc = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };
    String startKey = keyFunc.apply(start);
    String endKey = keyFunc.apply(end);
    graph.putIfAbsent(startKey, new java.util.ArrayList<>());
    graph.putIfAbsent(endKey, new java.util.ArrayList<>());

    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length != 2 * n) {
                // Skip invalid path entries
                continue;
            }
            int[] coord1 = new int[n];
            int[] coord2 = new int[n];
            System.arraycopy(path, 0, coord1, 0, n);
            System.arraycopy(path, n, coord2, 0, n);
            String key1 = keyFunc.apply(coord1);
            String key2 = keyFunc.apply(coord2);
            graph.putIfAbsent(key1, new java.util.ArrayList<>());
            graph.putIfAbsent(key2, new java.util.ArrayList<>());
            graph.get(key1).add(key2);
            graph.get(key2).add(key1); // assuming undirected paths
        }
    }

    // BFS to check connectivity
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
        for (String neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

