            if (dp[k - 1].isEmpty()) {
                continue;
            }
            for (int prevSum : dp[k - 1]) {
                dp[k].add(prevSum + num);
            }
        }
    }

    // Check for any k where a subset of size k has the required sum
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue; // target sum not integer
        }
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) {
