public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }

    // Generate Fibonacci numbers up to k
    int[] fibs = new int[50]; // 50 is more than enough for int range
    int size = 0;
    fibs[size++] = 1;
    fibs[size++] = 1;
    while (true) {
        long next = (long) fibs[size - 1] + fibs[size - 2];
        if (next > k || next > Integer.MAX_VALUE) {
            break;
        }
        fibs[size++] = (int) next;
    }

    // Greedy subtraction of the largest Fibonacci number <= remaining
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (fibs[i] <= remaining) {
            remaining -= fibs[i];
            count++;
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    java.util.Collections.reverse(large);
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        return large.get(k - small.size() - 1);
    }
}

public String makeGood(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            if (Math.abs(c - top) == 32) { // 'a' - 'A' == 32
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int[] max = new int[1];
    Set<String> seen = new HashSet<>();
    dfs(s, 0, seen, max);
    return max[0];
}

private void dfs(String s, int index, Set<String> seen, int[] max) {
    if (index == s.length()) {
        max[0] = Math.max(max[0], seen.size());
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            dfs(s, end, seen, max);
            seen.remove(sub);
        }
    }
}

