public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    // Minimum possible sum is n (all 'a's), maximum is 26*n (all 'z's)
    if (k < n || k > 26 * n) {
        return "";
    }
    StringBuilder sb = new StringBuilder();
    // Start with all 'a's
    for (int i = 0; i < n; i++) {
        sb.append('a');
    }
    int remaining = k - n; // how much we need to add to reach k
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each position can increase by at most 25
        sb.setCharAt(i, (char) ('a' + add));
        remaining -= add;
    }
    return sb.toString();
}

