public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = 0;
    stack[top] = -1; // sentinel
    int maxArea = 0;

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (stack[top] != -1 && heights[stack[top]] > currentHeight) {
            int height = heights[stack[top--]];
            int width = i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    int i = 0, j = 0;
    boolean up = true;
    while (index < m * n) {
        result[index++] = mat[i][j];
        if (up) {
            if (j == n - 1) {
                i++;
            } else if (i == 0) {
                j++;
            } else {
                i--;
                j++;
            }
        } else {
            if (i == m - 1) {
                j++;
            } else if (j == 0) {
                i++;
            } else {
                i++;
                j--;
            }
        }
        up = !up;
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }
    return build(n, n);
}

private static List<String> build(int n, int m) {
    if (n == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (n == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }
    List<String> sub = build(n - 2, m);
    List<String> res = new ArrayList<>();
    for (String s : sub) {
        if (n != m) {
            res.add("0" + s + "0");
        }
        res.add("1" + s + "1");
        res.add("6" + s + "9");
        res.add("8" + s + "8");
        res.add("9" + s + "6");
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    // Check for duplicate points
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }
    long x1 = points[0][0], y1 = points[0][1];
    long x2 = points[1][0], y2 = points[1][1];
    long x3 = points[2][0], y3 = points[2][1];
    long area2 = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);
    return area2 != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return -1;
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int next = Math.min(next2, Math.min(next3, next5));
        ugly[i] = next;
        if (next == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (next == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (next == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
        }
    }
    if (current > max) {
        max = current;
    }
    return max;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (Integer key : freq.keySet()) {
        if (freq.get(key) == 1) {
            sum += key;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    // Check if n is a perfect square
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1;
    }
    // Check if n can be expressed as sum of two perfect squares
    for (int i = 1; i <= sqrtN; i++) {
        int remainder = n - i * i;
        int sqrtRem = (int) Math.sqrt(remainder);
        if (sqrtRem * sqrtRem == remainder) {
            return 2;
        }
    }
    // Apply Legendre's three-square theorem
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) {
        return 4;
    }
    // If not 1, 2, or 4, then it must be 3
    return 3;
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    // Append the last word (if any)
    result.append(word.reverse());
    return result.toString();
}
